import { markdownToDocx } from "weizhi:docx";
export default markdownToDocx({
  inputPath: "notes/大纲.md",
  outputPath: "大纲.docx",
  title: "可选",
  defaultStyle: { font: "宋体", sizePt: 12 },
  headingStyles: { "1": { sizePt: 22, bold: true } }
});

import { buildDocx } from "weizhi:docx-build";
export default buildDocx({ title: "报告", defaultStyle: { font: "宋体", sizePt: 12 } }, (b) => {
  b.h1("摘要").p("正文段落。").bullet("要点一");
}, "out/report.docx");

import { readDocx } from "weizhi:docx";
const doc = readDocx("in/sample.docx");
const view = doc.textView();
const found = doc.grep("ABCD");
doc.replaceInBlock(found.matches[0].blockIndex, "ABCD", "EFGH");
doc.setBlockStyle(found.matches[0].blockIndex, { font: "宋体", sizePt: 14, bold: true });
export default { view: view.length, saved: doc.save("out/sample-edited.docx") };

import { unpackDocx, packDocx, validateDocx } from "weizhi:docx-raw";
import fs from "fs";
const unpacked = unpackDocx("in/sample.docx", { workDir: "tmp/ooxml" });
const xmlPath = unpacked.dir + "/word/document.xml";
let xml = fs.readFileSync(xmlPath).toString();
xml = xml.replace("ABCD", "NEW");
fs.writeFileSync(xmlPath, xml);
const v = validateDocx({ dir: unpacked.dir });
if (!v.ok) throw new Error("validateDocx failed");
export default packDocx(unpacked.dir, "out/raw-edited.docx");

import { renderPptx } from "weizhi:pptx";
export default renderPptx({
  title: "季度复盘",
  theme: "briefing",
  slides: [
    { layout: "title", title: "季度复盘", subtitle: "2026 Q3" },
    { layout: "bullets", title: "结论", items: ["收入 +12%"] },
    { layout: "shapes", shapes: [{ preset: "roundRect", col: 0, row: 0, colSpan: 6, rowSpan: 3, fill: "accent", text: "重点" }] }
  ]
}, "out/q3.pptx");

import { buildPptx } from "weizhi:pptx-build";
export default buildPptx({ title: "演示", theme: "dark" }, (b) => {
  b.title("演示", "副标题").steps("流程", ["发现", "修复", "上线"]);
}, "out/deck.pptx");

import { renderHtmlDeck } from "weizhi:html2pptx";
export default await renderHtmlDeck({
  htmlPath: "deck.html",
  output: "deck.pptx"
  // mode: "native"  // 仅用户要可编辑版时
});

const { exportVideo } = await import("weizhi:video");
const D = 300;
export default await exportVideo({
  width: 720, height: 1280,
  tracks: [{
    type: "image",
    clips: [
      { src: "a.jpg", startMs: 0, durationMs: 1000 },
      { src: "b.jpg", startMs: 1000 - D, durationMs: 1000,
        transition: { type: "crossfade", durationMs: D } }
    ]
  }, {
    type: "video",
    clips: [{ src: "clip.mp4", startMs: 1700, inMs: 0, outMs: 5000 }]
  }],
  output: "out.mp4"
});

import { readXlsx } from "weizhi:xlsx";
const wb = readXlsx("in/sales.xlsx");
const sh = wb.sheet(wb.sheetNames()[0]);
const summary = sh.summary();
sh.set("B2", 1200);
sh.setFormula("D2", "B2*(1+C2)");
export default { summary, saved: wb.save("out/sales-edited.xlsx") };

import { buildXlsx } from "weizhi:xlsx-build";
export default buildXlsx("out/budget.xlsx", (b) => {
  b.sheet("汇总").headers(["项目", "金额"]).rows([["差旅", 1000]]).formula("C2", "B2*1.13");
});

import { csvToXlsx } from "weizhi:xlsx";
export default csvToXlsx({
  inputPath: "data/sales.csv",
  outputPath: "out/sales.xlsx",
  sheetName: "销售"
});

import { readXlsx } from "weizhi:xlsx";
const wb = readXlsx("in/sales.xlsx");
const sh = wb.sheet(wb.sheetNames()[0]);
sh.addChart({
  type: "bar",
  title: "月度对比",
  anchor: "E2",
  series: [{ name: "销售额", categories: "A2:A13", values: "B2:B13" }]
});
export default wb.save("out/sales-chart.xlsx");

import { unpackXlsx, packXlsx, validateXlsx } from "weizhi:xlsx-raw";
import fs from "fs";
const up = unpackXlsx("in/s.xlsx", { workDir: "tmp/x" });
const p = up.dir + "/xl/sharedStrings.xml";
fs.writeFileSync(p, fs.readFileSync(p).toString().replace("旧词", "新词"));
const v = validateXlsx({ dir: up.dir });
if (!v.ok) throw new Error(JSON.stringify(v.errors));
export default packXlsx(up.dir, "out/s-edited.xlsx");
